package com.petcare.backend.controller; import static org.assertj.core.api.Assertions.assertThat; import static org.mockito.Mockito.*; import com.petcare.backend.dto.emr.request.CreateEmrRecordRequest; import com.petcare.backend.dto.emr.response.EmrRecordResponse; import com.petcare.backend.security.UserPrincipal; import com.petcare.backend.service.EmrRecordService; import java.util.*; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import org.springframework.http.HttpStatus;
@ExtendWith(MockitoExtension.class) class EmrRecordControllerTest {@Mock EmrRecordService service;@Mock UserPrincipal principal;EmrRecordController controller;@BeforeEach void init(){controller=new EmrRecordController(service);}@Test void endpointsDelegate(){CreateEmrRecordRequest req=new CreateEmrRecordRequest();EmrRecordResponse r=EmrRecordResponse.builder().id(1L).build();when(service.createEmrRecord(principal,req)).thenReturn(r);when(service.getEmrRecordsByPet(principal,2L)).thenReturn(List.of(r));when(service.getEmrRecordById(principal,1L)).thenReturn(r);assertThat(controller.createEmrRecord(principal,req).getStatusCode()).isEqualTo(HttpStatus.CREATED);assertThat(controller.getEmrRecordsByPet(principal,2L).getStatusCode()).isEqualTo(HttpStatus.OK);assertThat(controller.getEmrRecordById(principal,1L).getStatusCode()).isEqualTo(HttpStatus.OK);}}
